// The Sigil viewer inside Claude Code: a tool the agent calls and a
// /sigil-pane command (/sigil is the skill's), drawing a document in a pane
// (theme-coloured cells from pane.py, redrawn on every save, a simulated run
// stepped or played) or, in a multiplexer, in a split running view.py live.
// The repository's plugin/claude/README.md has the layout.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, UiOpenResult } from 'claude-code'

import type { Drawing, Playback, Split, ViewRequest } from '../types'
import {
  COMMAND, DEFAULT_WIDTH, PANE, VIEWS, RASTER_COLUMNS, START_SPEED, SUPERSEDED, TOOL, UNASKED_COLUMNS,
  aheadFrom, askedFrame, cropRows, detectMux, glyphs, heldBy, holdsWide, displayReport, drawArgv, drawnFrame, frameIndex, frameMs, herdrPaneOf, herdrReadyArgv,
  isDisplayChoice, lastFrame, layoutOf, layoutReport, nextDepth, nextSpeed, nextView, panTo, parseCommandArgs,
  parseDisplayArgs, parseDrawing, parseLayoutArgs, parseRequest, playbackFor, playTick, rasterCells, replyText,
  resolveDisplay, rowsWidth, runLines, shellQuote, slices, slot, splitArgv, splitStart, statusLine, viewArgv,
  windowFor, windowStart,
} from './logic'
import type { Ahead, Asked, Display, DisplayChoice, LayoutChoice } from './logic'

const request = atom({ plugin: 'sigil', key: 'request' } as const, null)
const drawing = atom({ plugin: 'sigil', key: 'drawing' } as const, null)
const failure = atom({ plugin: 'sigil', key: 'error' } as const, null)
const playback = atom({ plugin: 'sigil', key: 'playback' } as const, { at: 0, isPlaying: false })
const split = atom({ plugin: 'sigil', key: 'split' } as const, null)
const panX = atom({ plugin: 'sigil', key: 'panX' } as const, 0)
const speed = atom({ plugin: 'sigil', key: 'speed' } as const, START_SPEED)

const WATCH_MS = 1000 // how often the shown file is looked at
const ALIVE_MS = 3000 // a split whose follow loop touched its file this recently is up
const TITLE = 'Sigil'

type $ = EngineInterface

const TOOL_DESCRIPTION = [
  'Show a Sigil design to the person in a live viewer beside the conversation:',
  'the graph, tree or flow view (the design), or the run view (one simulated',
  'run as a timeline: a lane per participant, time left to right; the happy',
  'run when no scenario is given), redrawn on every save of the file. With',
  'scenario, the simulated run of that pathway (view.py --sim names: happy, or',
  'one from the scenarios list the reply gives), shown at frame (0-based, or',
  '"last") or played (play: true). Fields left out keep their last value.',
  'The reply says where it is shown, the summary, lint, and the run at that',
  'frame; it does not return the drawing (view.py --once prints that as text).',
  'Pick the view that fits: flow for request paths and failure routes;',
  'tree for composition, ownership and state machines, or a narrow pane;',
  'graph for the overall topology and fan-in of a small design; run to',
  'present a simulation (timing, retries, spawns, recursion). Tell the',
  'person in one sentence which view you picked and why.',
].join(' ')

const TOOL_SCHEMA = {
  type: 'object',
  properties: {
    file: { type: 'string', description: 'The .sigil file (relative to the working directory, or absolute).' },
    view: { type: 'string', enum: ['graph', 'tree', 'flow', 'run'], description: 'Which view (default flow).' },
    depth: { oneOf: [{ type: 'integer', minimum: 0 }, { const: 'all' }], description: 'Expansion depth (default 1).' },
    scenario: { type: 'string', description: 'A scenario to simulate; "" ends the run.' },
    frame: { oneOf: [{ type: 'integer', minimum: 0 }, { const: 'last' }], description: 'The run frame to show (default: the last).' },
    play: { type: 'boolean', description: 'Play the run from the frame shown (true) or pause it (false).' },
    payloads: { type: 'boolean', description: 'Show flow payloads.' },
  },
}

// Timers live with the module (a reload drops them and they are started
// again by the next draw); everything drawn lives in $.state.
let watchTimer: { cancel: () => void } | null = null
let playTimer: { cancel: () => void } | null = null
let seenMtime = 0
let columns = DEFAULT_WIDTH // the pane body's width as last drawn
let paneRows = 0 // the pane body's rows as last drawn (auto's layout picks by them; 0: unknown)
let layout: LayoutChoice = 'auto' // the plugin's `layout` option, set when the module loads
let drawingFor = '' // the request + size the latest redraw is for ('' once it drew; kept when it failed)
let drawSeq = 0 // counts redraws: only the latest stores what it drew
let isWindowing = false // a run window is being drawn (fetchWindow asks for one at a time)
let ahead: Ahead | null = null // the window after the shown one, drawn while a run plays (aheadFrom)
let isDrawingAhead = false // that window is being drawn

async function scriptPath($: $): Promise<string> {
  const built = `${$.plugin.root}/skills/sigil/scripts/pane.py`
  return (await $.fs.exists(built)) ? built : `${$.plugin.root}/scripts/pane.py`
}

async function muxEnv($: $) {
  return { herdr: await $.env.get('HERDR_ENV'), tmux: await $.env.get('TMUX'), zellij: await $.env.get('ZELLIJ') }
}

/** The file as an absolute path, or why it cannot be shown. */
async function located($: $, file: string): Promise<string | { error: string }> {
  const stat = await $.fs.stat(file, { resolve: true }).catch(() => undefined)
  if (stat === undefined || stat.realPath === undefined) return { error: `${file}: no such file` }
  if (stat.kind !== 'file') return { error: `${file}: not a file` }
  seenMtime = stat.mtimeMs
  return stat.realPath
}

/** What a redraw at `width` is for: the request and the pane's size (its rows
 * count only for auto, which picks by them). */
function drawKey(req: ViewRequest, width: number): string {
  return JSON.stringify([req, width, layout === 'auto' ? paneRows : 0])
}

/** pane.py's drawing of the request at `width`; a run's window from `from` (windowStart). */
async function runPane($: $, req: ViewRequest, width: number, from: number): Promise<Drawing | { error: string }> {
  const pane = { layout, from, ...(layout === 'auto' && paneRows > 0 ? { height: paneRows } : {}) }
  const ran = await $.process.run(drawArgv(await scriptPath($), req, width, pane), { timeoutMs: 60000 })
    .catch((err: unknown) => ({ exitCode: 1, stdout: '', stderr: String(err) }))
  return ran.exitCode === 0 ? parseDrawing(ran.stdout) : { error: ran.stderr.trim().split('\n').pop() ?? 'pane.py failed' }
}

/** Runs pane.py for the request at `width` and stores what it drew, unless a
 * later redraw started meanwhile (an older run finishing last never wins). A
 * run is drawn a window at a time: the one starting at `from` (windowStart),
 * else the one holding the frame shown. A failure keeps `drawingFor`, so the
 * pane does not ask for the same size again until the request or the size
 * changes (or a save redraws). */
async function redraw($: $, req: ViewRequest, width: number, from?: number): Promise<Drawing | { error: string }> {
  const key = drawKey(req, width)
  const seq = ++drawSeq
  drawingFor = key
  ahead = null
  const got = await runPane($, req, width, from ?? windowStart((await read($, playback)).at))
  if (seq !== drawSeq) return { error: SUPERSEDED }
  if ('error' in got) {
    await update($, failure, () => got.error)
    return got
  }
  drawingFor = ''
  got.width = width
  got.height = layout === 'auto' ? paneRows : 0
  await update($, drawing, () => got)
  await update($, failure, () => null)
  await update($, playback, p => ({ ...p, at: Math.min(p.at, lastFrame(got)) }))
  return got
}

/** Draws the run's window for showing `at` when the drawing does not hold it
 * (windowFor, one window at a time), and while it plays the window after it
 * (drawAhead). */
function fetchWindow($: $, req: ViewRequest, shown: Drawing, at: number, isPlaying: boolean): void {
  drawAhead($, req, shown, isPlaying)
  const from = windowFor(shown, at)
  if (from === null || isWindowing || heldBy(shown, ahead, drawKey(req, columns), at) !== shown) return
  isWindowing = true
  $.clock.after(0, () => void redraw($, req, columns, from).finally(() => { isWindowing = false }))
}

/** Draws the window after the shown one while a run plays (aheadFrom), kept
 * in `ahead` until the run plays into it; a redraw meanwhile drops it. */
function drawAhead($: $, req: ViewRequest, shown: Drawing, isPlaying: boolean): void {
  const from = aheadFrom(shown, isPlaying)
  const key = drawKey(req, columns)
  if (from === null || isDrawingAhead || (ahead !== null && ahead.key === key && ahead.drawing.first === from)) return
  isDrawingAhead = true
  const seq = drawSeq
  $.clock.after(0, () => void runPane($, req, columns, from).then(got => {
    if (seq === drawSeq && !('error' in got)) ahead = { key, drawing: { ...got, width: columns, height: layout === 'auto' ? paneRows : 0 } }
  }).finally(() => { isDrawingAhead = false }))
}

/** The drawing to play frame `at` from: the shown one, or the window drawn
 * ahead once the run has played into it (then shown, and no longer ahead). */
async function playedFrom($: $, req: ViewRequest, shown: Drawing, at: number): Promise<Drawing> {
  const held = heldBy(shown, ahead, drawKey(req, columns), at)
  if (held === shown) return shown
  ahead = null
  await update($, drawing, () => held)
  return held
}

function startWatch($: $): void {
  if (watchTimer !== null) return
  watchTimer = $.clock.every(WATCH_MS, async () => {
    const req = await read($, request)
    if (req === null) return
    const stat = await $.fs.stat(req.file).catch(() => undefined)
    if (stat === undefined || stat.mtimeMs === seenMtime) return
    seenMtime = stat.mtimeMs
    await redraw($, req, columns)
  })
}

function stopPlay(): void {
  playTimer?.cancel()
  playTimer = null
}

async function startPlay($: $): Promise<void> {
  if (playTimer !== null) return
  const ms = frameMs(await read($, speed))
  if (playTimer !== null) return
  playTimer = $.clock.every(ms, async () => {
    const was = await read($, drawing)
    const now = await read($, playback)
    const req = await read($, request)
    if (was === null || req === null || !now.isPlaying) return stopPlay()
    const shown = await playedFrom($, req, was, frameIndex(was, now) + 1)
    const next = playTick(shown, now)
    fetchWindow($, req, shown, next.at + 1, next.isPlaying)
    await update($, playback, () => next)
    if (!next.isPlaying) stopPlay()
  })
}

async function setPlayback($: $, next: Playback): Promise<void> {
  await update($, playback, () => next)
  if (next.isPlaying) await startPlay($)
  else stopPlay()
}

/** A speed step faster (+1) or slower (-1); a playing run goes on at it. */
async function setSpeed($: $, delta: number): Promise<void> {
  await update($, speed, s => nextSpeed(s, delta))
  stopPlay()
  if ((await read($, playback)).isPlaying) await startPlay($)
}

/** Shows `asked` in the mod's pane; `isAsked`: the person's /sigil (any width). */
async function showInPane($: $, asked: Asked, isAsked: boolean): Promise<string> {
  const before = await read($, request)
  const path = await located($, asked.request.file)
  if (typeof path !== 'string') return `sigil: ${path.error}`
  const req = { ...asked.request, file: path }
  const isNewRun = req.scenario !== before?.scenario || req.file !== before?.file
  await update($, request, () => req)
  await update($, panX, () => 0)
  const was = await read($, playback)
  const got = await redraw($, req, columns, windowStart(askedFrame(asked, was, isNewRun)))
  if ('error' in got) return `sigil: ${got.error}`
  const now = playbackFor(asked, got, was, isNewRun)
  await setPlayback($, now)
  startWatch($)
  // Opened by the person, the pane takes the keys (Esc hands them back); opened
  // by the agent, it never takes the prompt from them.
  const opened: UiOpenResult = await $.ui.open({ id: PANE, title: TITLE, ...(isAsked ? { focus: true as const } : {}) })
  const where = opened.isPlaced
    ? 'Shown in the sigil pane (redrawn on every save).'
    : isAsked
      ? `The sigil pane is open but not drawn: ${opened.reason}`
      : `The sigil pane is waiting: a pane the person did not ask for opens from ${UNASKED_COLUMNS} columns (${opened.reason}). `
        + `They can open it at any width with /${COMMAND}.`
  return replyText(got, frameIndex(got, now), now.isPlaying, where)
}

/** Writes the split's control file, opening the split first when none is up. */
async function showInSplit($: $, asked: Asked): Promise<string> {
  const path = await located($, asked.request.file)
  if (typeof path !== 'string') return `sigil: ${path.error}`
  const req = { ...asked.request, file: path }
  await update($, request, () => req)
  const mux = detectMux(await muxEnv($))
  if (mux === null) {
    return `sigil: display is multiplex, but no herdr, tmux or zellij session was found; /${COMMAND} display mod draws in the pane.`
  }
  const live = viewArgv(req, layout, splitStart(asked))
  const control = JSON.stringify({ argv: live })
  const held = await read($, split)
  if (held !== null && held.mux === mux && (await isAlive($, held))) {
    await $.fs.write(held.control, control)
    return about($, req, asked, `Shown in the ${mux} split running view.py live: ${shellQuote(live)}.`)
  }
  const tmp = (await $.env.get('TMPDIR')) ?? '/tmp'
  const opened: Split = { mux, control: `${tmp.replace(/\/$/, '')}/sigil-view-${crypto.randomUUID()}.json` }
  await $.fs.write(opened.control, control)
  const follow = ['python3', await scriptPath($), 'follow', opened.control]
  const ran = await $.process.run(splitArgv(mux, follow, mux === 'herdr' ? await $.env.get('HERDR_PANE_ID') : undefined))
  if (ran.exitCode !== 0) return `sigil: could not open a ${mux} split: ${ran.stderr.trim()}`
  if (mux === 'herdr') {
    const pane = herdrPaneOf(ran.stdout)
    if (pane === undefined) return 'sigil: herdr split gave no pane id'
    opened.pane = pane
    await $.process.run(herdrReadyArgv(pane), { timeoutMs: 10000 }).catch(() => undefined)
    await $.process.run(['herdr', 'pane', 'run', pane, shellQuote(follow)])
  } else if (mux === 'tmux') {
    opened.pane = ran.stdout.trim()
  }
  await update($, split, () => opened)
  return about($, req, asked, `Opened a ${mux} split running view.py live (it redraws on every save; `
    + `q closes it): ${shellQuote(live)}.`)
}

/** A split's reply: where, then the summary and the run where the split
 * starts it (splitStart) as pane.py reads them. */
async function about($: $, req: ViewRequest, asked: Asked, where: string): Promise<string> {
  const start = splitStart(asked)
  const ran = await $.process.run(drawArgv(await scriptPath($), req, DEFAULT_WIDTH, { from: windowStart(start.frame) }),
    { timeoutMs: 60000 }).catch(() => undefined)
  const got = ran?.exitCode === 0 ? parseDrawing(ran.stdout) : undefined
  if (got === undefined) return where
  if ('error' in got) return `${where}\nsigil: ${got.error}`
  const last = lastFrame(got)
  const at = drawnFrame(got, start.frame)
  return replyText(got, at, start.play && at < last, where)
}

async function isAlive($: $, held: Split): Promise<boolean> {
  const stat = await $.fs.stat(`${held.control}.alive`).catch(() => undefined)
  return stat !== undefined && (await $.clock.now()) - stat.mtimeMs < ALIVE_MS
}

async function show($: $, input: Record<string, unknown>, display: Display, isAsked: boolean): Promise<string> {
  // the file as the request stores it (its real path), so naming the shown
  // file again keeps its run
  const named = typeof input.file === 'string' && input.file !== '' ? await located($, input.file) : undefined
  if (typeof named === 'object') return `sigil: ${named.error}`
  const asked = parseRequest(named === undefined ? input : { ...input, file: named }, await read($, request))
  if ('error' in asked) return `sigil: ${asked.error}`
  return display === 'multiplex' ? showInSplit($, asked) : showInPane($, asked, isAsked)
}

/** The plugin's own row in /config for an option (`display`, `layout`):
 * `<plugin>.<option>` as the menu lists it (an inline or marketplace plugin may
 * carry a suffix). */
async function optionKey($: $, option: string): Promise<string> {
  const name = $.plugin.name
  const rows = await $.config.list().catch(() => [])
  const row = rows.find(r => r.key === `${name}.${option}`)
    ?? rows.find(r => r.key.endsWith(`.${option}`) && (r.key.startsWith(`${name}@`) || r.provider.plugin === name))
  return row?.key ?? `${name}.${option}`
}

/** `/sigil-pane display [VALUE]`: the setting in words, or the row changed.
 * A change reloads the module with the new options, so the reply is made
 * before the write and says what the next view does. */
async function displayCommand($: $, current: unknown, choice: DisplayChoice | undefined): Promise<string> {
  const key = await optionKey($, 'display')
  const env = await muxEnv($)
  const source = `/config ${key}`
  if (choice === undefined) return displayReport(isDisplayChoice(current) ? current : 'auto', source, env)
  if (choice === current) return `${displayReport(choice, source, env)} (unchanged)`
  const set = await $.config.set({ key, value: choice })
    .catch((err: unknown) => ({ deny: err instanceof Error ? err.message : String(err) }))
  if (set.deny !== undefined) return `sigil: display stays ${String(current)}: ${set.deny}`
  const resolved = resolveDisplay(choice, env)
  return `${displayReport(choice, source, env)}\nThe next view draws ${resolved === 'mod' ? 'in the sigil pane' : 'in a split'}.`
}

/** `/sigil-pane layout [VALUE]`: the setting in words, or the row changed (the
 * module reloads with it, as for display; the next drawing is laid out so). */
async function layoutCommand($: $, current: unknown, choice: LayoutChoice | undefined): Promise<string> {
  const key = await optionKey($, 'layout')
  const source = `/config ${key}`
  const shown = (await read($, drawing))?.layout
  if (choice === undefined) return layoutReport(layoutOf(current), source, shown)
  if (choice === current) return `${layoutReport(choice, source, shown)} (unchanged)`
  const set = await $.config.set({ key, value: choice })
    .catch((err: unknown) => ({ deny: err instanceof Error ? err.message : String(err) }))
  if (set.deny !== undefined) return `sigil: layout stays ${layoutOf(current)}: ${set.deny}`
  return `${layoutReport(choice, source)}\nThe next drawing is laid out ${choice === 'auto' ? 'as fits the pane best' : `to ${choice}`}.`
}

/** A key of the pane's: a new request redrawn, or a playback step. */
async function press($: $, change: (req: ViewRequest) => ViewRequest): Promise<void> {
  const req = await read($, request)
  if (req === null) return
  const next = change(req)
  await update($, request, () => next)
  await update($, panX, () => 0)
  await redraw($, next, columns)
}

export const register: Register = (on, options) => {
  layout = layoutOf(options.layout)
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.tool.register({ name: 'view', description: TOOL_DESCRIPTION, inputSchema: TOOL_SCHEMA })
    await $.command.register({
      name: 'sigil-pane',
      description: 'Show a Sigil file in the viewer pane (any width), reopen the last one, or set where it draws (display) or how a wide drawing fits (layout)',
      argumentHint: '[FILE] [graph|tree|flow|run] [depth N|all] [sim SCENARIO] [frame N|last] [play] | display [mod|multiplex|auto] | layout [auto|wrap|pan]',
    })
    return started
  })

  on('tool.call', { tool: 'mcp__sigil__view' }, async ($, e) => {
    const display = resolveDisplay(options.display, await muxEnv($))
    const { tool: _tool, tool_use_id: _id, ...input } = e as Record<string, unknown>
    return { result: await show($, input, display, false) }
  }).catch(($, e, next) => ({ result: `sigil: the viewer failed (${next.error.kind}); view.py --once still prints the drawing.` }))

  on('command.run', { command: 'sigil-pane' }, async ($, e) => {
    const asked = parseDisplayArgs(e.args)
    if (asked !== null) return { text: 'error' in asked ? `sigil: ${asked.error}` : await displayCommand($, options.display, asked.choice) }
    const laid = parseLayoutArgs(e.args)
    if (laid !== null) return { text: 'error' in laid ? `sigil: ${laid.error}` : await layoutCommand($, options.layout, laid.choice) }
    const display = resolveDisplay(options.display, await muxEnv($))
    const input = parseCommandArgs(e.args)
    if (Object.keys(input).length === 0 && display === 'mod' && (await read($, request)) !== null) {
      await $.ui.open({ id: PANE, title: TITLE, focus: true })
      return { text: 'Sigil pane opened.' }
    }
    return { text: await show($, input, display, true) }
  })

  on('ui.close', { id: 'sigil' }, async ($, e, next) => {
    stopPlay()
    watchTimer?.cancel()
    watchTimer = null
    await update($, playback, p => ({ ...p, isPlaying: false }))
    return next(e)
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: 'sigil' }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const req = await read($, request)
    const shown = await read($, drawing)
    const error = await read($, failure)
    const now = await read($, playback)
    const pace = await read($, speed)
    const width = Math.max(20, Math.min(e.props.bodyColumns, RASTER_COLUMNS))
    const rows = e.props.scroll.bodyRows
    const resized = shown !== null && (shown.width !== width || (layout === 'auto' && shown.height !== rows))
    if (req !== null && resized && drawingFor !== JSON.stringify([req, width, layout === 'auto' ? rows : 0])) {
      columns = width
      paneRows = rows
      drawingFor = drawKey(req, width)
      $.clock.after(0, () => void redraw($, req, width))
    }
    if (req !== null) startWatch($)
    if (shown === null || req === null) {
      return (
        <Box flexDirection="column">
          <Text dimColor>{error ?? `No Sigil file shown yet: /${COMMAND} FILE, or ask the agent to show one.`}</Text>
        </Box>
      )
    }
    const at = frameIndex(shown, now)
    fetchWindow($, req, shown, at, now.isPlaying)
    const drawn = shown.frames[slot(shown, at)] ?? []
    const across = rowsWidth(drawn)
    const x = await read($, panX)
    const isPanned = shown.layout === 'pan' && across > width
    const frame = isPanned ? cropRows(drawn, x, width) : drawn
    const isRun = shown.status !== undefined
    const told = runLines(shown, at)
    const body = (cells: typeof drawn, key: string) => {
      if (e.surface === 'terminal' && !holdsWide(cells)) {
        const { Raster } = $.ui.resolve(e)
        const cols = Math.max(1, Math.min(width, rowsWidth(cells) || 1))
        return slices(cells).map((part, i) => (
          <Raster key={`${key}${i}`} columns={cols} rows={Math.max(1, part.length)}
            cells={rasterCells(part.length > 0 ? part : [[]], shown.styles, cols)} />
        ))
      }
      return cells.map(row => (
        <Text wrap="truncate">
          {row.map(([text, id]) => {
            const [fg, bg, bold] = shown.styles[id] ?? [null, null, false]
            return <Text color={fg ?? undefined} backgroundColor={bg ?? undefined} bold={bold}>{glyphs(text)}</Text>
          })}
        </Text>
      ))
    }
    const step = (delta: number) => () =>
      setPlayback($, { at: Math.max(0, Math.min(at + delta, lastFrame(shown))), isPlaying: false })
    // Docked, the drawing takes the room the info rows leave and they sit at the
    // bottom; inline, the pane is as tall as what it holds.
    const fill = e.props.placement === 'dock' ? { height: e.props.scroll.bodyRows } : {}
    return (
      <Box flexDirection="column" {...fill}>
        <Text bold wrap="truncate">{statusLine(shown, req, at, now.isPlaying, pace)}</Text>
        {error !== null && <Text color="error" wrap="truncate">✖ {error}</Text>}
        <Box flexDirection="column" flexGrow={1}>{body(frame, 'frame')}</Box>
        {told !== null && (told.path !== null ? body(told.path, 'path')
          : <Text dimColor wrap="truncate">{told.trail}</Text>)}
        {told !== null && <Text bold wrap="truncate">{told.now}</Text>}
        {shown.legend.length > 0 && body(shown.legend, 'legend')}
        <Text dimColor wrap="wrap">{shown.summary}</Text>
        {shown.lint.map(line => <Text dimColor wrap="wrap">{line}</Text>)}
        <Box flexDirection="row" gap={1}>
          {VIEWS.map((view, i) => (
            <Button key={`view-${view}`} plain hotkey={String(i + 1)}
              label={view === req.view ? `[${view}]` : view}
              onPress={() => press($, r => ({ ...r, view }))} />
          ))}
          <Button key="view" plain hotkey="t" label="cycle"
            onPress={() => press($, r => ({ ...r, view: nextView(r.view) }))} />
          <Button key="depth" plain hotkey="d" label="depth"
            onPress={() => press($, r => ({ ...r, depth: nextDepth(r.depth) }))} />
          {isRun && <Button key="play" plain hotkey="p" label={now.isPlaying ? 'pause' : 'play'}
            onPress={() => setPlayback($, {
              at: !now.isPlaying && at >= lastFrame(shown) ? 0 : at, isPlaying: !now.isPlaying,
            })} />}
          {isRun && <Button key="back" plain hotkey="b" label="back" onPress={step(-1)} />}
          {isRun && <Button key="next" plain hotkey="n" label="next" onPress={step(1)} />}
          {isPanned && <Button key="left" plain hotkey="h" label="◀"
            onPress={() => update($, panX, p => panTo(p, -Math.floor(width / 2), across, width))} />}
          {isPanned && <Button key="right" plain hotkey="l" label="▶"
            onPress={() => update($, panX, p => panTo(p, Math.floor(width / 2), across, width))} />}
          {isRun && <Button key="slower" plain hotkey="s" label="slower" onPress={() => setSpeed($, -1)} />}
          {isRun && <Button key="faster" plain hotkey="f" label="faster" onPress={() => setSpeed($, 1)} />}
          <Text dimColor>{e.props.isFocused ? '· esc: prompt' : '· ctrl+x tab: keys'}</Text>
        </Box>
      </Box>
    )
  })
}

